      "title": "土地改革の約束と農民",
      "body": [
        "さらに共産党は、1947年に中国土地法<ruby>大綱<rt>たいこう</rt></ruby>を発表し、<strong class=\"source-bold\">地主の土地所有の廃止と農民への土地均分</strong>を約束したから、農民は「これは地主を倒す戦いだ」と思って人民解放軍（共産党軍）に参加！ 共産党がだんだん優位になった。"
      ],
