      "title": "土法炉による製鉄",
      "body": [
        "そして、「<strong class=\"source-bold\">鉄鋼生産でイギリスを抜く！</strong>」という目標も、中国にそんな製鉄所はないから、「ならば農民の力を結集しろ〜」と言って、人民公社に自家製の炉（<ruby>土法炉<rt>どほうろ</rt></ruby>）をつくらせ、<strong class=\"source-bold\">農民に製鉄をさせた</strong>んだよ。"
      ],
