      "id": "modern-c05-l23-p01-073",
      "title": "文化大革命の呼びかけ",
      "body": [
        "そして、共産党内に紛れ込んだブルジョワ階級を洗い出して権力を奪い取る「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プロレタリア文化大革命</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">文化大革命</strong></span>／<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">文革</strong></span>】</strong>」を全国に呼びかけたんだ。ここから壮絶な<strong class=\"source-bold\">権力闘争</strong>が始まったんだ！。"
      ],
