      "id": "modern-c05-l23-p01-075",
      "title": "劉少奇と鄧小平の追放",
      "body": [
        "これを止めようとした<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>劉少奇<rt>りゅうしょうき</rt></ruby></strong></span>は「<strong class=\"source-bold\">実権派の最高指導者</strong>」とされ、補佐役の<strong class=\"source-bold\"><ruby>鄧小平<rt>とうしょうへい</rt></ruby></strong>も「第2の実権派」として<strong class=\"source-bold\">政界から追放</strong>、さらに<strong class=\"source-bold\">劉少奇は共産党から永久除名</strong>されて監禁され、1969年に病死した。"
      ],
      "plainBody": [
        "これを止めようとした劉少奇は「実権派の最高指導者」とされ、補佐役の鄧小平も「第2の実権派」として政界から追放、さらに劉少奇は共産党から永久除名されて監禁され、1969年に病死した。"
      ],
