      "body": [
        "保守派は共産党の一党支配を維持するため、民主化運動を容認しようとした党総書記の<strong class=\"source-bold\"><ruby>胡耀邦<rt>こようほう</rt></ruby></strong>の責任を追及し始めたから、<ruby>鄧小平<rt>とうしょうへい</rt></ruby>は胡耀邦を辞めさせたんだけど、民主化要求はさらに高まるんだ。"
      ],
