      "id": "modern-c05-l23-p01-114",
      "title": "1989年のゴルバチョフ訪中",
      "body": [
        "1989年、まさに東欧で社会主義政権が次々に倒れた（<strong class=\"source-bold\">東欧革命</strong>）のと同じ年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゴルバチョフが訪中</strong></span>して中ソ対立を終わらせ<strong class=\"source-bold\">中ソ関係を正常化</strong>すると、この影響で「ソ連のペレストロイカと同じように、中国も自由化しろ〜」という<strong class=\"source-bold\">民主化運動</strong>が盛り上がった。"
      ],
      "plainBody": [
        "1989年、まさに東欧で社会主義政権が次々に倒れた（東欧革命）のと同じ年、ゴルバチョフが訪中して中ソ対立を終わらせ中ソ関係を正常化すると、この影響で「ソ連のペレストロイカと同じように、中国も自由化しろ〜」という民主化運動が盛り上がった。"
      ],
