      "body": [
        "じゃあ、続いて韓国だ。<span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">第20回</span>に話した朝鮮戦争の続きだよ。初代大統領の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>李<rt>イ</rt></ruby><ruby>承晩<rt>スンマン</rt></ruby></strong></span>は<strong class=\"source-bold\"><ruby>米韓<rt>べいかん</rt></ruby>相互防衛条約</strong>を結んでアメリカ中心の反共軍事同盟の一角となったけど、ほかの国とは状況が違う。"
      ],
