      "id": "modern-c05-l23-p03-014",
      "title": "北方外交と南北朝鮮の国連加盟",
      "body": [
        "そして、1988年の<strong class=\"source-bold\">ソウル＝オリンピック</strong>をきっかけに<strong class=\"source-bold\">ソ連との対話</strong>を始め、共産圏との和解を目指した。この北方外交により、ソ連のゴルバチョフとの間で<strong class=\"source-bold\">韓ソ国交樹立</strong>を実現し、1991年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南北朝鮮が国連に同時加盟</strong></span>したよ。"
      ],
