export const sourcePages = {
  "424": "<h2>424</h2>\n<h1><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第23回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">戦後の東アジア</span></h1>\n<p>前回までは欧米を中心に<ruby>冷戦<rt>れいせん</rt></ruby>終結まで一気に進んだけど、ここからはアジアの戦後史を見ていくよ。今回は、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">中国を中心とする東アジア</strong></u>だ！</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">大きくつかもう！</span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span></td></tr><tr><td><strong class=\"source-bold\">戦後の中華人民共和国</strong></td><td><strong class=\"source-bold\">戦後の台湾</strong></td><td><strong class=\"source-bold\">戦後の韓国</strong></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">425〜432ページ</span></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">433ページ</span></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">434〜435ページ</span></td></tr></tbody></table></div>\n<blockquote><p>東アジアは資本主義VS.社会主義から国が分裂していくよ</p></blockquote>\n<p>日中戦争が終わった直後から内戦となった中国は、共産党の勝利で<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">中華人民共和国</strong></u>ができたよ。そこから社会主義国家の建設が始まるんだけど、なかなかうまくはいかなかった。「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\"><ruby>大躍進<rt>だいやくしん</rt></ruby></strong></u>」、「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">調整政策</strong></u>」、そして「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">文化大革命</strong></u>」……壮絶な権力闘争が待っているんだ。さらに、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">アメリカ</strong></u>、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ソ連</strong></u>、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">インド</strong></u>との関係など、国際関係も刻々と変化していくよ。そして、権力闘争の末にたどり着いたところは？ さらに、共産党に敗れた<ruby>蒋介石<rt>しょうかいせき</rt></ruby>が逃れた<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">台湾</strong></u>や分断国家になった<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">韓国</strong></u>は、<ruby>独裁<rt>どくさい</rt></ruby>政治になっちゃうんだ……。</p>\n<p>それじゃ、日本の周辺を取り巻く東アジア戦後史、じっくり見ていこう。</p>",
  "425": "<h2>425</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後の中華人民共和国</u></p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">戦後の中華人民共和国</strong></span></h3>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <span data-source-color=\"black\" data-source-background=\"pink\" style=\"background-color:#fbe1e1\"><strong class=\"source-bold\">戦後の中華人民共和国（冷戦終結まで）</strong></span></h3>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\"><ruby>毛沢東<rt>もうたくとう</rt></ruby>体制</strong>……<strong class=\"source-bold\">ソ連の<ruby>援助<rt>えんじょ</rt></ruby></strong>で社会主義建設を進める</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ友好同盟相互援助条約</strong></span>［1950.2］……ソ連が中国を全面的に援助</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>社会主義建設</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">土地改革法</strong></span>［1950.6］……農民の土地所有を進める</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次五カ年計画</strong></span>［1953〜57］……ソ連の援助で<strong class=\"source-bold\">重工業優先の工業化</strong>と<strong class=\"source-bold\">農業集団化</strong></p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ対立</strong></span>開始［1956］……フルシチョフの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリン批判</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">平和共存政策</strong></span>が契機</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">大躍進</strong></span>」［1958〜］　※急激な社会主義化</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人民公社</strong></span>の創設［1958］……極端な農村重視の社会主義化　<span data-source-color=\"green\" style=\"color:#315837\">➡</span>生産性の大幅減退</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">毛沢東・<ruby>劉少奇<rt>りゅうしょうき</rt></ruby>体制</strong>……共産党の実権は毛沢東が握る</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">劉少奇</strong></span>が<strong class=\"source-bold\">国家主席</strong>に就任［1959］……<strong class=\"source-bold\">調整政策（一部に資本主義を復活）</strong>を実施</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><strong class=\"source-bold\">中ソ対立が公開論争に発展</strong>（対立の表面化）［1960］　<span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ国境紛争</strong></span>が<ruby>頻発<rt>ひんぱつ</rt></ruby></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">文化大革命</strong></span>［1966〜77］……思想闘争の形をとった、毛沢東周辺の権力闘争</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>紅衛兵<rt>こうえいへい</rt></ruby></strong></span>の運動　<span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">劉少奇・<ruby>鄧小平<rt>とうしょうへい</rt></ruby></strong>らの失脚［1968］</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>林彪<rt>りんぴょう</rt></ruby></strong></span>を毛沢東の後継者に指名［1969］　<span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">林彪の失脚後、「四人組」</strong>が勢力拡大</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>周恩来<rt>しゅうおんらい</rt></ruby>の死</strong></span>［1976.1］　<span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">第1次<ruby>天安門<rt>てんあんもん</rt></ruby>事件</strong>が発生</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">毛沢東の死</strong></span>［1976.9］　<span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">「四人組」逮捕</strong>。<strong class=\"source-bold\"><ruby>華国鋒<rt>かこくほう</rt></ruby></strong>が共産党主席に就任</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">鄧小平</strong></span>体制［1977〜97］　※<strong class=\"source-bold\">最高実力者</strong>として実権を握る</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">改革・開放政策</strong></span>」……<strong class=\"source-bold\">資本主義の一部復活</strong>と<strong class=\"source-bold\">西側諸国との関係改善</strong>で経済再建</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">四つの現代化</strong></span>」……<strong class=\"source-bold\">農業・工業・国防・科学技術</strong>の近代化</p>\n<p><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人民公社解体</strong></span>を決定［1982］　<span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">生産責任制</strong>へ転換</p>\n<p><span data-source-color=\"green\" style=\"color:#315837\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次天安門事件</strong></span>［1989］……ゴルバチョフ訪中や東欧革命も背景</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 日本の敗戦で「<ruby>抗日<rt>こうにち</rt></ruby>民族統一戦線」が崩壊して、国共内戦が再開！</strong></span></h4>\n<p>日中戦争が始まると、<strong class=\"source-bold\">蒋介石の国民党</strong>と毛沢東の<strong class=\"source-bold\">共産党</strong>は「協力して日本と戦おう！」という<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次国共合作</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">抗日民族統一戦線</strong></span>】</strong>をつくったけど、日中戦争が終わると協力する理由はもうない。ただ、終戦直後は<strong class=\"source-bold\">ソ連も蒋介石の国民政府を</strong>支持し、アメリカも内戦を望んでいなかったから、1945年には<strong class=\"source-bold\"><ruby>双十<rt>そうじゅう</rt></ruby>協定</strong>で国民党・共産党が「内戦はやらない！」って約束した。でもすぐに内戦が始まったんだ。「これはマズい」と思ったアメリカのマーシャルが<ruby>仲介<rt>ちゅうかい</rt></ruby>して<strong class=\"source-bold\">国共停戦協定</strong>が成立すると、<strong class=\"source-bold\">政治協商会議</strong>で今後の体制について一応は合意した。でも、またまた蒋介石が内戦を再開した。そして米ソ対立が激しくなるにつれて、蒋介石の国民政府は<strong class=\"source-bold\">アメリカ</strong>との関係を強めて権力を維持しようとしたんだ。対する<strong class=\"source-bold\">共産党</strong>はソ連</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "426": "<h2>426</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第23回</strong></span> 戦後の東アジア</p></blockquote>\n<p>の力を借りて北部に拠点を拡大し、1947年には戦争中の<strong class=\"source-bold\"><ruby>八路軍<rt>はちろぐん</rt></ruby></strong>・<strong class=\"source-bold\"><ruby>新四軍<rt>しんしぐん</rt></ruby></strong>をもとにして<strong class=\"source-bold\">人民解放軍</strong>をつくって対抗したよ。</p>\n<p>さらに共産党は、1947年に中国土地法<ruby>大綱<rt>たいこう</rt></ruby>を発表し、<strong class=\"source-bold\">地主の土地所有の廃止と農民への土地均分</strong>を約束したから、農民は「これは地主を倒す戦いだ」と思って人民解放軍（共産党軍）に参加！ 共産党がだんだん優位になった。</p>\n<p>一方、国民政府が支配する地域では、軍事費とアメリカからの<ruby>借款<rt>しゃっかん</rt></ruby>で<strong class=\"source-bold\">急激なインフレ</strong>が起こり、貿易の自由化で外国製品が大量に流入して<strong class=\"source-bold\">貿易赤字が拡大</strong>して経済は大混乱。資本家も「もはや<ruby>蒋介石<rt>しょうかいせき</rt></ruby>ではダメだ」と考え始めたよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ついに共産党が内戦に勝利し、中華人民共和国の建国を宣言！</strong></span></h4>\n<p>蒋介石の人気がなくなると、人民解放軍は<strong class=\"source-bold\"><ruby>北京<rt>ペキン</rt></ruby>、<ruby>南京<rt>ナンキン</rt></ruby></strong>を制圧してほぼ中国全土の支配権を握ったよ。そして<strong class=\"source-bold\">蒋介石派を除く</strong>グループの代表が<strong class=\"source-bold\">人民政治協商会議</strong>を開き、<ruby>毛沢東<rt>もうたくとう</rt></ruby>が発表した<strong class=\"source-bold\">新民主主義</strong>に基づいて、<strong class=\"source-bold\">労働者と農民の同盟</strong>による<strong class=\"source-bold\">社会主義国</strong>をつくることを決め、1949年10月には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">北京</strong></span>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中華人民共和国</strong></span>の成立を宣言したんだ。主席は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">毛沢東</strong></span>、初代首相は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>周恩来<rt>しゅうおんらい</rt></ruby></strong></span>だよ。一方、内戦に敗れた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">蒋介石</strong></span>は台湾に逃れて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中華民国政府</strong></span>を維持し（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">台湾国民政府</strong></span>）、その後もアメリカの支援を受け続けたから<strong class=\"source-bold\">国連<ruby>安保理<rt>あんぽり</rt></ruby>では常任理事国</strong>のままだ。こうして中国には「<strong class=\"source-bold\">北京</strong>」と「<strong class=\"source-bold\"><ruby>台北<rt>タイペイ</rt></ruby></strong>」に<strong class=\"source-bold\">2つの中国政府</strong>ができ、各国は「<strong class=\"source-bold\">どちらと国交を結ぶか？</strong>」を選ばなきゃいけなくなった（「<strong class=\"source-bold\">2つの中国</strong>」問題）。でも、大陸を支配する北京政府（中華人民共和国）に対して、台湾の大きさって九州と同じくらいなんだけどね……。</p>\n<p>中華人民共和国が成立すると、<strong class=\"source-bold\">ソ連や東欧、インドが建国直後に承認</strong>し、1950年には<strong class=\"source-bold\">労働党政権</strong>（<strong class=\"source-bold\">アトリー</strong>内閣）だった<strong class=\"source-bold\">イギリス</strong>も続いて承認したよ。イギリスは<ruby>香港<rt>ホンコン</rt></ruby>を持ってるから、攻め込まれても困るしね。ただ、<ruby>冷戦<rt>れいせん</rt></ruby>の時代だから、資本主義陣営の国はほとんど承認しなかった。そして1950年2月には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ友好同盟相互援助条約</strong></span>が結ばれ、<strong class=\"source-bold\">中国は社会主義陣営の一員となる</strong>とともに、ソ連が中国を経済的・技術的にも支援することになったんだ。そのかわりに中国は、<strong class=\"source-bold\">モンゴル人民共和国</strong>の独立を認めたよ。さらに、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">朝鮮戦争</strong></span>ではソ連と協力した中国が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人民<ruby>義勇軍<rt>ぎゆうぐん</rt></ruby></strong></span>を派遣して北朝鮮を助けるなど、中ソ両国の関係は深まっていったんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ソ連の援助で中国の社会主義建設が進むはずが……中ソ論争が始まる！</strong></span></h4>\n<p>国共内戦の時からずっと土地改革を進めていた毛沢東は、1950年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">土地改革法</strong></span>をつくって、地主から土地を奪って<strong class=\"source-bold\">農民に土地を分配</strong>した。ただし、都市と農村とを明確に分けて、戸籍の移動を制限したよ。さらに毛沢東は工場などを国有化すると、<strong class=\"source-bold\">三反五反運動</strong>（三害〔官僚の不正〕と五害〔資本家の不正〕への反対運動）を通じて、民衆に「社会主義は正義の味方だ」って思わせようとした。そして1953年には<strong class=\"source-bold\">ソ連の援助</strong>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次五カ年計画</strong></span>を開始！ ソ連と同じように、<strong class=\"source-bold\">重工業優先の工業化</strong>と<strong class=\"source-bold\">急速な農業の集団化</strong>を進めたんだけど、いきなり社会主義化された国内は大混乱だ。でも、毛沢東は突き進んだ。1954年には<strong class=\"source-bold\">中華人民共和国憲法</strong>を</p>",
  "427": "<h2>427</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後の中華人民共和国</u></p></blockquote>\n<p>制定して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国家主席</strong></span>となり、ソ連型の社会主義建設を進めたんだよ。</p>\n<p>しかし、ソ連との協力は長くは続かなかった……。1956年にソ連のフルシチョフが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スターリン批判</strong></span>をおこない<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">平和共存政策</strong></span>を発表、いきなり「資本主義と共存する！」と言われて迷った毛沢東は、さらにソ連軍がハンガリーに<ruby>介入<rt>かいにゅう</rt></ruby>したのを見て、「本当にソ連の言うとおりでいいのか？」と考えた。それに、農民ばかりの中国でソ連と同じように重工業を優先するのはムリだ……。<strong class=\"source-bold\">中国は少しずつ独自の道を進み始め</strong>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ対立</strong></span>が始まったよ。</p>\n<p>そして、民衆も「本当にこれでいいのか？」っていう疑問を持った。だって、「共産党が土地をくれた〜」って喜んでたら、いきなり土地を取られんだよ、そりゃ怒る。これに対し毛沢東は<strong class=\"source-bold\">言論を自由化</strong>して、知識人に「共産党を批判しろー」って言い始めた（<strong class=\"source-bold\"><ruby>百花斉放<rt>ひゃっかせいほう</rt></ruby>・<ruby>百家争鳴<rt>ひゃっかそうめい</rt></ruby>運動</strong>）。知識人の批判を毛沢東が論破すれば、「やっぱり毛沢東が一番すごい！」って形で国内がまとまると思ったんだよ。しかし……そううまくはいかない。知識人からは予想以上に批判があふれて、止められなくなった。すると一転、<strong class=\"source-bold\">共産党を批判した人を「右派分子」として<ruby>弾圧<rt>だんあつ</rt></ruby></strong>したんだ（<strong class=\"source-bold\">反右派闘争</strong>）。なんと、摘発されて農村に送られた人は50万人以上！ ていうか、これって共産党への反対派をあぶりだそうとしたんじゃないの？</p>\n<blockquote><p>毛沢東は知識人に「もっと批判を！」と文句を言わせて、最後はまとめて弾圧した。こりゃダマしたな</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 「<ruby>大躍進<rt>だいやくしん</rt></ruby>」で中国は大混乱！ 毛沢東にかわって<ruby>劉少奇<rt>りゅうしょうき</rt></ruby>が国家主席になった</strong></span></h4>\n<p>1957年、毛沢東がソ連を訪問した時、フルシチョフが「ソ連は15年でアメリカを追い越す」って宣言したから、毛沢東も「<strong class=\"source-bold\">中国も15年で鉄鋼生産を増やし、イギリスに追いつき、追い越す</strong>」というプランを打ち出した。毛沢東の頭の中では、「ソ連がアメリカを抜き、中国がイギリスを抜けば、社会主義が資本主義を追い越せる」っていう夢が広がってたんだ。</p>\n<p>ソ連から帰国した毛沢東は、1958年から民衆を動員して急速な発展を目指す「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">大躍進</strong></span>」運動（政策）を始めた。「多く、早く、立派に、むだなく社会主義を建設する」というスローガンを掲げて、まず<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人民公社</strong></span>をつくって<strong class=\"source-bold\">農村を一気に社会主義化した</strong>。これは、2000戸くらいの農民を1つの共同体にまとめて、農地・工場などをすべて「みんなのもの（集団所有）」にして、集団労働をして、収穫は平等に分けるというものだ。しかも<strong class=\"source-bold\">政治・経済・教育・文化・軍事</strong>などをすべて<strong class=\"source-bold\">人民公社に集約</strong>し、食事までも「公共食堂」でおこなうという徹底ぶりだ。これが、毛沢東に言わせると「革命的な生活」なんだって。</p>\n<p>そして、「<strong class=\"source-bold\">鉄鋼生産でイギリスを抜く！</strong>」という目標も、中国にそんな製鉄所はないから、「ならば農民の力を結集しろ〜」と言って、人民公社に自家製の炉</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "428": "<h2>428</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第23回</strong></span> 戦後の東アジア</p></blockquote>\n<p>（<ruby>土法炉<rt>どほうろ</rt></ruby>）をつくらせ、<strong class=\"source-bold\">農民に製鉄をさせた</strong>んだよ。でも、逆に農地がほったらかしになって<strong class=\"source-bold\">農業生産は大幅に減少</strong>！。しかも、農民がつくった鉄はほとんど使いものにならなかった。それに、集団労働で「同じ収入」しかもらえないから、みんなサボり始めた。誰だって、「1時間働いても8時間働いても給料は同じ」って言われたら、1時間しか働かないよ。こうしてますます農業生産が減り、ついに<strong class=\"source-bold\">大<ruby>飢饉<rt>ききん</rt></ruby>が起き</strong>て、さらに、<strong class=\"source-bold\">中ソ対立の激化</strong>からソ連が<strong class=\"source-bold\">中ソ技術協定を<ruby>破棄<rt>はき</rt></ruby>した</strong>ことでトドメを刺された。「<ruby>大躍進<rt>だいやくしん</rt></ruby>」の期間に、なんと2000万人以上が<ruby>餓死<rt>がし</rt></ruby>！ どう考えても<ruby>人災<rt>じんさい</rt></ruby>だよ。こうなると、<strong class=\"source-bold\">社会主義化のペースをゆるめる</strong>しかなくなり、1959年に<strong class=\"source-bold\"><ruby>毛沢東<rt>もうたくとう</rt></ruby>が表向きは引退</strong>し、かわって<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>劉少奇<rt>りゅうしょうき</rt></ruby></strong></span>が<strong class=\"source-bold\">国家主席になった</strong>。とはいっても、<strong class=\"source-bold\">毛沢東は共産党主席</strong>のままだから、権力は握り続けてるからね。</p>\n<blockquote><p>鉄鋼生産が間に合わなかった人たちは、中華鍋とか鉄柱、しまいには線路や橋まで溶かして固めて「鉄ができた」って言ったらしい……</p></blockquote>\n<p>国家主席になった劉少奇は「とにかく経済を再建しなきゃいけない！」と考えて、<strong class=\"source-bold\"><ruby>鄧小平<rt>とうしょうへい</rt></ruby></strong>を補佐役に<strong class=\"source-bold\">調整政策</strong>を始めたよ。土地を農民に返し、労働に応じた分配をおこない、家庭内での副業も認めるなど、<strong class=\"source-bold\">一部に資本主義を復活</strong>した。すると自分が働いた分が収入になるから農民のやる気も戻り、1965年ごろには食糧生産が大躍進を始める前の水準まで回復、<strong class=\"source-bold\">経済が上向き</strong>になってきた。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ 1960年代に入ると、中印国境<ruby>紛争<rt>ふんそう</rt></ruby>と中ソ国境紛争で隣国との関係が悪化！</strong></span></h4>\n<p>それじゃここで、中国を取り巻く国際関係について見ておこう。まずは<strong class=\"source-bold\">中国とインド</strong>の抱える<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チベット問題</strong></span>だ。1950年に<strong class=\"source-bold\">人民解放軍がチベットに進軍</strong>し、翌年には、中国軍による支配を完了させた。ただ、チベット貴族やラマ教の僧の反発はずっと続き、ついに1959年、首都の<strong class=\"source-bold\">ラサ</strong>で反乱が起きた。この<strong class=\"source-bold\">チベット反乱</strong>を中国軍が大<ruby>弾圧<rt>だんあつ</rt></ruby>！ 身の危険を感じた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ダライ＝ラマ14世</strong></span>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">インドへ<ruby>亡命<rt>ぼうめい</rt></ruby></strong></span>した。この時、インドがチベットを<ruby>擁護<rt>ようご</rt></ruby>したから<strong class=\"source-bold\">インドと中国の対立が深まり</strong>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中印国境紛争</strong></span>に発展したんだ。戦争は中国が優位だったけど、中ソ対立を抱える<strong class=\"source-bold\">ソ連がインドを支持</strong>したから、今度は<strong class=\"source-bold\">中国とソ連の対立</strong>が激しくなった。</p>\n<p>中ソ対立が激化した原因はほかにもある！ <strong class=\"source-bold\">フルシチョフの訪米</strong>、さらに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キューバ危機</strong></span>での譲歩を見て、中国は「<strong class=\"source-bold\">ソ連はアメリカに従属している</strong>」と批判し、ついに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中ソ対立</strong></span>が<strong class=\"source-bold\">公開論争に発展</strong>したよ。中国がソ連を「社会主義から逸脱した“<strong class=\"source-bold\">修正主義</strong>”（資本主義への妥協）」と批判すると、ソ連も中国を「世界情勢が理解できない“<strong class=\"source-bold\"><ruby>教条主義<rt>きょうじょうしゅぎ</rt></ruby></strong>”（ただの個人<ruby>独裁<rt>どくさい</rt></ruby>）」だと批判した。さらに1963年に米英ソが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">部分的<ruby>核<rt>かく</rt></ruby>実験禁止条約</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">PTBT</strong></span>】</strong>を結ぶと、毛沢東は「米ソによる中国<ruby>封<rt>ふう</rt></ruby>じ込めじゃないか！」と怒って<strong class=\"source-bold\">独自の核開発</strong>を進め、翌年には<strong class=\"source-bold\"><ruby>原爆<rt>げんばく</rt></ruby>実験に成功</strong>して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">核保有国</strong></span>となった。さらに、1969年には<strong class=\"source-bold\"><ruby>珍宝島<rt>ちんぽうとう</rt></ruby>【ダマンスキー島】</strong>で武力衝突が起きるなど<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中</strong></span></p>",
  "429": "<h2>429</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後の中華人民共和国</u></p></blockquote>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ国境紛争</strong></span>も激化、もはや中国とソ連の関係は修復不可能だよ。</p>\n<h4><strong class=\"source-bold\">〈戦後の中国〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">ソ連</strong></td><td>珍宝島（ダマンスキー島）</td></tr><tr><td><strong class=\"source-bold\">モンゴル人民共和国</strong></td><td><span data-source-color=\"green\" data-source-marker=\"point\" data-source-outline-color=\"black\" style=\"color:#315837\">●</span>北京</td></tr><tr><td><strong class=\"source-bold\">中華人民共和国</strong></td><td><span data-source-color=\"green\" data-source-marker=\"point\" data-source-outline-color=\"black\" style=\"color:#315837\">●</span>上海</td></tr><tr><td><strong class=\"source-bold\">インド</strong></td><td><span data-source-color=\"pink\" data-source-marker=\"star\" data-source-outline-color=\"black\" style=\"color:#f0a0a0\">★</span>廈門</td></tr><tr><td><span data-source-color=\"pink\" data-source-marker=\"star\" data-source-outline-color=\"black\" style=\"color:#f0a0a0\">★</span>汕頭</td><td><span data-source-color=\"pink\" data-source-marker=\"star\" data-source-outline-color=\"black\" style=\"color:#f0a0a0\">★</span>深圳</td></tr><tr><td><span data-source-color=\"pink\" data-source-marker=\"star\" data-source-outline-color=\"black\" style=\"color:#f0a0a0\">★</span>珠海</td><td><span data-source-color=\"pink\" data-source-marker=\"point\" data-source-outline-color=\"black\" style=\"color:#f0a0a0\">●</span>香港</td></tr><tr><td><span data-source-color=\"pink\" data-source-marker=\"star\" data-source-outline-color=\"black\" style=\"color:#f0a0a0\">★</span>海南島</td><td></td></tr></tbody></table></div>\n<blockquote><p><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">中ソ国境紛争［1969］</span>　<span data-source-color=\"red\" data-source-marker=\"battle\" style=\"color:#e52715\">⚔</span> <span data-source-color=\"red\" data-source-marker=\"battle\" style=\"color:#e52715\">⚔</span></p>\n<p><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">チベット反乱（ラサ）</span>　<span data-source-color=\"red\" data-source-marker=\"battle\" style=\"color:#e52715\">⚔</span></p>\n<p><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">中印国境紛争</span>　<span data-source-color=\"red\" data-source-marker=\"battle\" style=\"color:#e52715\">⚔</span> <span data-source-color=\"red\" data-source-marker=\"battle\" style=\"color:#e52715\">⚔</span></p></blockquote>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"pink\" data-source-marker=\"star\" data-source-outline-color=\"black\" style=\"color:#f0a0a0\">★</span></td><td>経済特区</td></tr></tbody></table></div>\n<blockquote><p>「中ソ」と「中印」2つの国境紛争は、インド史でも大事だから、ちゃんとおさえておこう！</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">◀ ついに始まった毛沢東の猛反撃。文化大革命の嵐が吹き荒れた！</strong></span></h4>\n<p>じゃあ、中国国内に戻るよ。<strong class=\"source-bold\">劉少奇が調整政策で経済再建</strong>を進めると、立場が危うくなるのが「大躍進」をやった人……っていうか、<strong class=\"source-bold\">毛沢東じゃん</strong>。だって、「調整政策の成功＝<strong class=\"source-bold\">“大躍進”の失敗</strong>」ってことでしょ……。しかも中ソ対立で、毛沢東は<strong class=\"source-bold\">ソ連のフルシチョフとも対立</strong>してる。このころの毛沢東は、<strong class=\"source-bold\">ベトナム戦争でアメリカとの対立</strong>が厳しくなり、<strong class=\"source-bold\">中ソ論争も激化</strong>して、孤立感を強めてたから、「とにかく強いリーダーシップを確立しなければ」と焦ってたからね。毛沢東は、劉少奇やフルシチョフを「資本主義の手先」と決めつけ、「このままでは資本家や地主が復活してしまう」と焦った。そこで、「地主やブルジョワの手先をあぶりだせ」と大衆をあおり、さらに「<strong class=\"source-bold\">党内の資本主義の道に進む</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">実権派</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>走資<rt>そうし</rt></ruby>派</strong></span>】</strong>を打倒せよ」と主張した。そして、共産党内に紛れ込んだブルジョワ階級を洗い出して権力を奪い取る「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">プロレタリア文化大革命</strong></span> <strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">文化大革命</strong></span>／<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">文革</strong></span>】</strong>」を全国に呼びかけたんだ。ここから壮絶な<strong class=\"source-bold\">権力闘争</strong>が始まったんだ！。</p>\n<p>毛沢東の呼びかけに最初に応えたのは学生たちだ。<strong class=\"source-bold\">毛沢東語録</strong>を手にした「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>紅衛<rt>こうえい</rt></ruby><ruby>兵<rt>へい</rt></ruby></strong></span>」と名乗る<strong class=\"source-bold\">学生たち</strong>が「学校当局の“実権派”を打倒せよ！」と叫ぶと、毛沢東</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>",
  "430": "<h2>430</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第23回</strong></span> 戦後の東アジア</p></blockquote>\n<p>が「<strong class=\"source-bold\"><ruby>造反有理<rt>ぞうはんゆうり</rt></ruby></strong>（反抗には理由がある）」と支持したから、暴力的なデモや集会が拡大して、高校や大学の機能はマヒ。これを止めようとした<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>劉少奇<rt>りゅうしょうき</rt></ruby></strong></span>は「<strong class=\"source-bold\">実権派の最高指導者</strong>」とされ、補佐役の<strong class=\"source-bold\"><ruby>鄧小平<rt>とうしょうへい</rt></ruby></strong>も「第2の実権派」として<strong class=\"source-bold\">政界から追放</strong>、さらに<strong class=\"source-bold\">劉少奇は共産党から永久除名</strong>されて監禁され、1969年に病死した。そして<ruby>紅衛<rt>こうえい</rt></ruby><ruby>兵<rt>へい</rt></ruby>の暴挙はさらにエスカレートし、「実権派」と決めつけた人に三角帽子をかぶせて街を引きずり回し、暴行した。ただ、統制がきかなくなった紅衛兵たちも軍に<ruby>鎮<rt>ちん</rt></ruby><ruby>圧<rt>あつ</rt></ruby>され、さんざん利用されたうえ、農村に追放されたんだ。</p>\n<p>劉少奇が消されると、文化大革命を推進してきた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>林彪<rt>りんぴょう</rt></ruby></strong></span>が<ruby>毛沢東<rt>もうたくとう</rt></ruby>の後継者になった。しかし、<strong class=\"source-bold\">米ソ両国との同時対決を避けたい毛沢東や<ruby>周恩来<rt>しゅうおんらい</rt></ruby>が対米接近を図った</strong>ことで、強く反米を主張する林彪と対立した。失脚の危機を感じた<strong class=\"source-bold\">林彪は毛沢東暗殺のクーデタを計画</strong>したけど失敗し、飛行機でソ連に逃亡する途中で<ruby>墜落<rt>ついらく</rt></ruby>死した。<strong class=\"source-bold\">林彪も飛行機ごと消された</strong>んだよ！。</p>\n<p>林彪の失脚後、今度は<strong class=\"source-bold\">毛沢東夫人</strong>の<strong class=\"source-bold\"><ruby>江青<rt>こうせい</rt></ruby></strong>を中心に<strong class=\"source-bold\">毛沢東にゴマをすって</strong>権力を強めた<strong class=\"source-bold\">四人組</strong>（江青・<ruby>張春橋<rt>ちょうしゅんきょう</rt></ruby>・<ruby>姚文元<rt>ようぶんげん</rt></ruby>・<ruby>王洪文<rt>おうこうぶん</rt></ruby>）と、なんとかして<strong class=\"source-bold\">文化大革命を終わらせたい</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">周恩来</strong></span>が対立した。四人組は「<strong class=\"source-bold\"><ruby>批林批孔<rt>ひりんひこう</rt></ruby>運動</strong>（表向きは林彪と<ruby>孔子<rt>こうし</rt></ruby>を批判、本当は周恩来批判）」で周恩来を攻撃し、一方の周恩来は<strong class=\"source-bold\">鄧小平を復活</strong>させ、<strong class=\"source-bold\">新憲法</strong>を制定して<strong class=\"source-bold\">国家主席の地位を廃止</strong>すると、鄧小平を中心に経済の立て直しを図った。この時期にマトモなのは周恩来くらいだよ……。</p>\n<p>しかし……1976年1月、激しい権力闘争のなかで<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">周恩来が死去</strong></span>すると、四人組が調子に乗って「周恩来も<ruby>走資<rt>そうし</rt></ruby>派である」と言い出した。しかし、民衆は「周恩来さまのほうが正しいじゃないか……」ってわかっていたから、四人組に反発！ 全国で周恩来追悼の運動が起きた。焦った四人組は軍と警察を動員し、<strong class=\"source-bold\"><ruby>北京<rt>ペキン</rt></ruby>の<ruby>天安<rt>てんあん</rt></ruby><ruby>門<rt>もん</rt></ruby>広場で周恩来を追悼していた民衆を<ruby>弾圧<rt>だんあつ</rt></ruby></strong>、多数の負傷者を出したよ（<strong class=\"source-bold\">天安門事件</strong>〔<strong class=\"source-bold\">第1次</strong>〕）。さらに四人組は、事件の黒幕だと決めつけた<strong class=\"source-bold\">鄧小平を失脚させた</strong>んだ。</p>\n<p>ただ、周恩来の死に一番ショックを受けていたのは毛沢東だ……。さらに追い討ちをかけるように7月には<strong class=\"source-bold\"><ruby>朱徳<rt>しゅとく</rt></ruby>も亡くなった</strong>。2人とも一緒に「長征」をやった同志だし、朱徳はかつて「朱毛」と言われたほど行動をともにした盟友だ。この二人のあとを追うように、9月には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">毛沢東も死去</strong></span>したんだ。</p>\n<p>じゃあここでひと区切りして、<span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">第22回</span>で話した文化大革命の時期の外交を簡単に確認しておくよ。</p>\n<p>1971年にアメリカの<strong class=\"source-bold\">大統領補佐官キッシンジャーの訪中</strong>でニクソン訪中が決まり、その見返りに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中国の国連代表権交代</strong></span>が実現したよね。さらに、1972年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニクソン訪中</strong></span>で毛沢東とニクソンの会見も実現して、アメリカは<strong class=\"source-bold\">事実上中華人民共和国を承認</strong>した。さらに同じ年、<strong class=\"source-bold\"><ruby>田中角栄<rt>たなかかくえい</rt></ruby></strong>首相の訪中で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日中国交正常化</strong></span>も実現した。この時日本は、台湾を中国の領土と確認して<strong class=\"source-bold\">台湾政府とは断交</strong>し、中国も<strong class=\"source-bold\">日本への<ruby>賠償<rt>ばいしょう</rt></ruby>は請求しない</strong>ことに合意したよ。</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"red\" data-source-border-shape=\"circle\" style=\"border:2px solid #e52715;border-radius:50%;padding:0.15em 0.3em;display:inline-block\"><strong class=\"source-bold\">ソ連</strong></span></td><td><strong class=\"source-bold\">冷戦</strong><span data-source-color=\"brown\" style=\"color:#a43725\">↔</span></td><td><span data-source-border=\"black\" data-source-border-shape=\"circle\" style=\"border:2px solid #001000;border-radius:50%;padding:0.15em 0.3em;display:inline-block\"><strong class=\"source-bold\">米</strong></span></td></tr><tr><td><strong class=\"source-bold\">中ソ対立</strong><span data-source-color=\"brown\" style=\"color:#a43725\">↕</span></td><td></td><td><strong class=\"source-bold\">米中接近</strong></td></tr><tr><td><span data-source-border=\"pink\" data-source-border-shape=\"circle\" style=\"border:2px solid #f0a0a0;border-radius:50%;padding:0.15em 0.3em;display:inline-block\"><strong class=\"source-bold\">中国</strong></span></td><td><span data-source-color=\"black\" data-source-marker=\"double-line\" style=\"color:#001000;border-bottom:3px double #001000\">╱</span></td><td></td></tr></tbody></table></div>",
  "431": "<h2>431</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">1</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後の中華人民共和国</u></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>\n<h3><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">文化大革命が終わり、鄧小平による「改革・開放」政策が始まった！</strong></span></h3>\n<p>毛沢東の死から1カ月もたたないうちに、<strong class=\"source-bold\">四人組は逮捕</strong>された。彼らに権力を握らせたくない党の幹部と軍が先手を打ったんだね。そして、周恩来のあとに首相となった<strong class=\"source-bold\"><ruby>華国鋒<rt>かこくほう</rt></ruby></strong>が共産党主席となり、<strong class=\"source-bold\">文化大革命の終結を宣言</strong>したよ。</p>\n<p>華国鋒は、かつて周恩来が唱えた「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">四つの現代化</strong></span>（<strong class=\"source-bold\">農業・工業・国防・科学技術</strong>の近代化）」を再提起したものの、<strong class=\"source-bold\">毛沢東路線を続けようとしていた</strong>。一方、再復活した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">鄧小平</strong></span>は<strong class=\"source-bold\">経済発展を優先したかった</strong>から両者は対立し、最終的に<strong class=\"source-bold\">鄧小平が実権を握った</strong>んだ。ちなみに鄧小平の肩書きは「<strong class=\"source-bold\">党副主席・副総理</strong>」だけど一番エラい！。だから「<strong class=\"source-bold\">最高実力者</strong>」って言われるよ。何？ 「副」なのにエラいの？ ここは肩書を見ちゃダメ！ 中国で一番エラいのは誰かというと「<strong class=\"source-bold\">エラい人がエラい！</strong>」。ここまでの中国の最高実力者は「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">毛沢東</strong></span>、<strong class=\"source-bold\">そのあとが鄧小平</strong>」、この2人だけだよ。</p>\n<blockquote><p>文化大革命での死者は約2000万人！ なんらかの被害を受けた人は1億人ともいわれてるよ</p></blockquote>\n<p>鄧小平は毛沢東について「文化大革命では誤りを犯したが、功績のほうが大きい」と決議し、さらに劉少奇の名誉回復を決めると、文化大革命は「人民に大きな災難を与えた」と認めたんだ。そして、鄧小平は周恩来が唱えた「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">四つの現代化</strong></span>」に基づいて国を建て直し、<strong class=\"source-bold\">国内では「改革」、対外的には「開放」</strong>を進めたよ。これが「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">改革・開放政策</strong></span>」だ。簡単に言うと「経済再建のためのお金がない→外国資本を導入したい→だから、西側の資本主義国と仲良くする」ってことね。そこで、1978年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日中平和友好条約</strong></span>を結び、さらに翌年正式に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米中国交正常化</strong></span>を実現、中国は<strong class=\"source-bold\">中ソ友好同盟相互援助条約を<ruby>破棄<rt>はき</rt></ruby></strong>したんだ。</p>\n<p>そして、外国資本導入のために<strong class=\"source-bold\">経済特区</strong>をつくったよ。これは、<strong class=\"source-bold\">対外貿易や外国企業の進出を進める</strong>ために特別の地域を設定するもので、<strong class=\"source-bold\"><ruby>広東<rt>カントン</rt></ruby>省</strong>や<strong class=\"source-bold\"><ruby>福建<rt>ふっけん</rt></ruby>省</strong>の4都市（<ruby>深圳<rt>しんせん</rt></ruby>・<ruby>珠海<rt>しゅかい</rt></ruby>・<ruby>汕頭<rt>スワトウ</rt></ruby>・<ruby>廈門<rt>アモイ</rt></ruby>）と<ruby>海南島<rt>かいなんとう</rt></ruby>など、<ruby>華南<rt>かなん</rt></ruby>の沿岸部につくられた。さらに農村では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人民公社が解体</strong></span>されて<strong class=\"source-bold\">生産請負制</strong>を導入し、<strong class=\"source-bold\">事実上の土地私有を認めた</strong>んだ。こうした経済改革は、要するに<strong class=\"source-bold\">資本主義を復活</strong>するものだけど、鄧小平はのちにこう言った。「“社会主義＝計画経済”、“資本主義＝<ruby>市場<rt>しじょう</rt></ruby>経済”と決めつけてはいけない。社会主義の発展のために市場経済を導入する」ってね。これが「<strong class=\"source-bold\">社会主義市場経済</strong>」だ。ヘリクツだと思ったでしょ。要するに「<strong class=\"source-bold\">資本主義だけど、共産党一党<ruby>独裁<rt>どくさい</rt></ruby></strong>」ってことだよ。</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ソ連のペレストロイカの影響で民主化運動が激化！</strong></span></h3>\n<p>改革・開放政策が進むと、<strong class=\"source-bold\">インフレによる生活苦や民主化抑圧への不満</strong>が広がった。ちょうどソ連で<strong class=\"source-bold\">ゴルバチョフ</strong>が「<strong class=\"source-bold\">ペレストロイカ</strong>」を打ち出し、対外的にも「新思考外交」を進めたのと同じ時期だ！ しかし中国は、<strong class=\"source-bold\">経済改革は進めても政</strong></p>",
  "432": "<h2>432</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第23回</strong></span> 戦後の東アジア</p></blockquote>\n<p><strong class=\"source-bold\">治改革をするつもりはなかった</strong>から、これに反発した<strong class=\"source-bold\">民主化運動が始まった</strong>。保守派は共産党の一党支配を維持するため、民主化運動を容認しようとした党総書記の<strong class=\"source-bold\"><ruby>胡耀邦<rt>こようほう</rt></ruby></strong>の責任を追及し始めたから、<ruby>鄧小平<rt>とうしょうへい</rt></ruby>は胡耀邦を辞めさせたんだけど、民主化要求はさらに高まるんだ。</p>\n<p>1989年、まさに東欧で社会主義政権が次々に倒れた（<strong class=\"source-bold\">東欧革命</strong>）のと同じ年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ゴルバチョフが訪中</strong></span>して中ソ対立を終わらせ<strong class=\"source-bold\">中ソ関係を正常化</strong>すると、この影響で「ソ連のペレストロイカと同じように、中国も自由化しろ〜」という<strong class=\"source-bold\">民主化運動</strong>が盛り上がった。そして、<strong class=\"source-bold\">胡耀邦前総書記の死去</strong>をきっかけに、学生などを中心とする100万人近い市民が<strong class=\"source-bold\"><ruby>北京<rt>ペキン</rt></ruby>の<ruby>天安門<rt>てんあんもん</rt></ruby>広場</strong>に集まり、民主化を求めるデモを始めたんだ。これに対し、<strong class=\"source-bold\"><ruby>李鵬<rt>りほう</rt></ruby></strong>らの保守派が戦車部隊でデモを<ruby>蹴散<rt>けち</rt></ruby>らし、<strong class=\"source-bold\">武力で<ruby>弾圧<rt>だんあつ</rt></ruby>した</strong>。政府側の発表で死者は300人、実際には数倍いるとみられている。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">天安門事件</strong></span>（第2次）の様子はテレビを通じて全世界に流されたから、国際的に「中国は人権を守れ」と批判された。そして、デモをあおったとされる<strong class=\"source-bold\"><ruby>趙紫陽<rt>ちょうしよう</rt></ruby>が失脚</strong>し、<strong class=\"source-bold\"><ruby>江沢民<rt>こうたくみん</rt></ruby></strong>が共産党総書記になった。鄧小平は、このころから健康が悪化したからだろう、表舞台に登場しなくなった。</p>\n<blockquote><p>天安門事件……テレビで流れた「戦車で人が<ruby>潰<rt>つぶ</rt></ruby>される」映像は、僕もいまだに覚えてるよ</p></blockquote>\n<h3><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">鄧小平が死去したあとの国家主席は「江沢民→<ruby>胡錦濤<rt>こきんとう</rt></ruby>→<ruby>習近平<rt>しゅうきんぺい</rt></ruby>」</strong></span></h3>\n<p>李鵬との権力闘争に勝った<strong class=\"source-bold\">江沢民は国家主席</strong>となり、1997年に鄧小平が死去すると実権を握ったよ。彼の最初の大舞台は1997年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>香港<rt>ホンコン</rt></ruby>返還</strong></span>の式典だよ。香港は、1984年にイギリスの<strong class=\"source-bold\">サッチャー</strong>政権と結んだ<strong class=\"source-bold\">香港返還協定</strong>により、中国領の<strong class=\"source-bold\">香港特別行政区</strong>となった。そして、鄧小平が唱えた「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">一国二制度</strong></span>（1国のなかに2つの経済体制）」論により、香港では<strong class=\"source-bold\">50年間は資本主義体制が保障</strong>されたんだ。その後、1998年から江沢民の<ruby>腹心<rt>ふくしん</rt></ruby>だった<ruby>朱鎔基<rt>しゅようき</rt></ruby>が首相となって改革を進め、<strong class=\"source-bold\">中国は高度経済成長を実現</strong>した。さらに1999年には香港と同じ「一国二制度」を適用して、ポルトガルから<strong class=\"source-bold\">マカオが返還</strong>された。まあ、中国国内も<strong class=\"source-bold\">社会主義<ruby>市場<rt>しじょう</rt></ruby>経済</strong>（というか実質的には資本主義）だから、本国も香港もマカオも経済の体制はあまり変わらないけどね。そして、2001年には<strong class=\"source-bold\">世界貿易機関【WTO】にも加盟</strong>したんだ。</p>\n<p>その後、2003年に江沢民が引退すると<strong class=\"source-bold\">胡錦濤</strong>が国家主席に、<ruby>温家宝<rt>おんかほう</rt></ruby>が首相になった。中国は2008年の<strong class=\"source-bold\">北京オリンピック</strong>に向けて経済成長が加速し、2010年には日本を抜いて<strong class=\"source-bold\">国内総生産【GDP】が世界2位</strong>になった。しかし、経済成長の陰で<strong class=\"source-bold\">国民の<ruby>貧富<rt>ひんぷ</rt></ruby>格差が拡大</strong>している。しかも「社会主義」の看板は下ろしてないから、「社会主義は平等じゃないのか！」という<ruby>貧困<rt>ひんこん</rt></ruby>層の不満がたまっているよ。そして、2012年に日本の<ruby>野田<rt>のだ</rt></ruby>首相が<strong class=\"source-bold\"><ruby>尖閣<rt>せんかく</rt></ruby>諸島</strong>の国有化を発表すると、中国国内の不満も重なって<strong class=\"source-bold\">大規模な反日</strong>デモが巻き起こった。2013年には<strong class=\"source-bold\">習近平</strong>が<strong class=\"source-bold\">国家主席に就任</strong>したけど、国内の不満の解消が課題だね。これ以降は、<span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">第26回</span>で解説するね。</p>",
  "433": "<h2>433</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後の台湾</u></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">2</span> <span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">戦後の台湾</strong></span></h3>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\">◀</span> <span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">国連から追放されたあとは経済発展を目指し、民主化も実現！</strong></span></h4>\n<p>日本の敗戦後、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>蒋介石<rt>しょうかいせき</rt></ruby></strong></span>は軍を送って台湾を中華民国の支配下に置き、民衆の不満も抑え込んだ。1947年に起きた<strong class=\"source-bold\"><ruby>二<rt>に</rt></ruby>・<ruby>二八<rt>にはち</rt></ruby>事件</strong>では、民衆の抗議運動を武力弾圧して多数の犠牲者を出した。これ以後、<strong class=\"source-bold\"><ruby>本省人<rt>ほんしょうじん</rt></ruby>（台湾出身の人）と外省人（大陸から来た人）</strong>の対立が続くことになるよ。</p>\n<p>1949年、共産党に敗れた<strong class=\"source-bold\">蒋介石は台湾に逃げて</strong>きて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中華民国</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">台湾国民政府</strong></span>）を維持し、<strong class=\"source-bold\">軍による<ruby>独裁<rt>どくさい</rt></ruby>体制</strong>を敷いたんだ。1951年の日本との<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サンフランシスコ平和条約</strong></span>で正式に台湾返還が決まると、翌年の<ruby>日華<rt>にっか</rt></ruby>平和条約で日本は台湾を<ruby>放棄<rt>ほうき</rt></ruby>、台湾も日本への<ruby>賠償<rt>ばいしょう</rt></ruby>請求権を放棄した。さらに、1954年にはアメリカと<strong class=\"source-bold\"><ruby>米華<rt>べいか</rt></ruby>相互防衛条約</strong>を結んで中国に対抗し、在華米軍が台湾と台湾海峡を守ったんだ。</p>\n<p>しかし、1971年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">中国の国連代表権が交代</strong></span>すると、<strong class=\"source-bold\">台湾は国連を追放</strong>された。つまり、国際的には「<strong class=\"source-bold\">台湾は独立国ではなく、中華人民共和国の一部</strong>」ということになった。でも、独自の政府・通貨などもあるから、事実上は独立した「国家」だ。そこで、「“経済的に”国際社会での存在感を示す」ことにしたんだ。</p>\n<p>蒋介石の死後、息子の<strong class=\"source-bold\"><ruby>蒋経国<rt>しょうけいこく</rt></ruby></strong>が<ruby>総統<rt>そうとう</rt></ruby>になると、<strong class=\"source-bold\">輸出産業を発展させて高度経済成長に成功</strong>し、本省人を政府に登用したり、野党（<strong class=\"source-bold\">民進党</strong>）を認めたりと、<strong class=\"source-bold\">政治の民主化</strong>も始まった。そして、蒋経国の死後、副総統から昇格したのが<strong class=\"source-bold\">初の台湾出身</strong>（本省人）の総統<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>李登輝<rt>りとうき</rt></ruby></strong></span>だ。李登輝はさらに政治的な民主化を進め、<strong class=\"source-bold\">台湾初の総統直接選挙</strong>をやって<strong class=\"source-bold\">再選</strong>されたよ。ちなみに彼は日本の<ruby>統治<rt>とうち</rt></ruby>時代に京都大学で学んだこともあるんだよ。</p>\n<p>そして、2000年の総統選挙では、<strong class=\"source-bold\">民進党</strong>の<strong class=\"source-bold\"><ruby>陳水扁<rt>ちんすいへん</rt></ruby></strong>が当選し、ついに国民党以外から総統が選ばれた。民進党は<strong class=\"source-bold\">台湾独立を主張</strong>する政党だから、その第一歩として<strong class=\"source-bold\">世界貿易機関【WTO】への加盟</strong>を実現した。つまり、「経済的には独立」ってことだね。ただ、2008年の<strong class=\"source-bold\">世界金融危機の影響で経済が落ち込み</strong>、「中国との貿易で経済を再建しよう！」って主張する<strong class=\"source-bold\">国民党の<ruby>馬英九<rt>ばえいきゅう</rt></ruby></strong>が総統になり、中国と台湾の経済的な関係を強めたんだけど、親中政策への反発から<strong class=\"source-bold\">国民の「台湾意識」が強まった</strong>んだ。</p>\n<blockquote><p>現在の台湾は、IT産業が日本以上に発展しているよ。それにとても親日的な「国」だ</p></blockquote>\n<p>そして、2016年の総統選挙では、「台湾意識」の高揚を背景に<strong class=\"source-bold\">民進党の<ruby>蔡英文<rt>さいえいぶん</rt></ruby></strong>が当選し、<strong class=\"source-bold\">台湾初の女性総統</strong>になったよ。彼女は、台湾の自立を維持するためにあくまで「現状維持」を主張していたんだけど、習近平体制の中国が台湾支配を目論んで圧力を強めるなか、<strong class=\"source-bold\">台湾の自立を守るためにアメリカ合衆国との連携</strong>を強めているんだ。</p>",
  "434": "<h2>434</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第23回</strong></span> 戦後の東アジア</p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <span data-source-background=\"pink\" data-source-border=\"red\" style=\"background-color:#f7caca;border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">戦後の韓国</strong></span></h3>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\">◀</span> <span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">朝鮮戦争が休戦しても法的には戦争中。軍部の力が強くなった！</strong></span></h4>\n<p>じゃあ、続いて韓国だ。<span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">第20回</span>に話した朝鮮戦争の続きだよ。初代大統領の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>李<rt>イ</rt></ruby><ruby>承晩<rt>スンマン</rt></ruby></strong></span>は<strong class=\"source-bold\"><ruby>米韓<rt>べいかん</rt></ruby>相互防衛条約</strong>を結んでアメリカ中心の反共軍事同盟の一角となったけど、ほかの国とは状況が違う。<strong class=\"source-bold\">朝鮮戦争は正式には終わっていない</strong>ので韓国では軍の力が強くなり、<strong class=\"source-bold\">在韓米軍が韓国軍の指揮権を持つ</strong>など、アメリカへの従属を深めたんだ。こうした李承晩政権への不満から<strong class=\"source-bold\">学生を中心とする民衆暴動</strong>（四月革命）が起こり、李承晩はハワイに<ruby>亡命<rt>ぼうめい</rt></ruby>、<strong class=\"source-bold\"><ruby>張勉<rt>チャンミョン</rt></ruby>政権ができた</strong>。</p>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\">◀</span> <span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\"><ruby>朴正熙<rt>パクチョンヒ</rt></ruby>が軍部クーデタで権力を握る！ 長い軍事政権の時代が始まった</strong></span></h4>\n<p>1961年になると、<strong class=\"source-bold\">軍部クーデタ</strong>によって<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">朴正熙</strong></span>が権力を握った。彼は、なんとしても北朝鮮に対して優位に立ちたかった。今のイメージで考えちゃだめだよ！ 独立した時の韓国と北朝鮮を比べると、<strong class=\"source-bold\">経済的にも軍事的にも北朝鮮のほうが強かった</strong>んだもん。「とにかく経済発展を」と思ったけどお金がない……。「だったら、<strong class=\"source-bold\">日本との国交正常化</strong>でお金を出させ、経済を発展させよう！」。こうして1965年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日韓基本条約</strong></span>を<ruby>締結<rt>ていけつ</rt></ruby>すると、日本は<strong class=\"source-bold\">韓国政府を朝鮮半島唯一の政権</strong>と認め、<ruby>賠償<rt>ばいしょう</rt></ruby>ではなく、無償3億ドル、有償2億ドルの<strong class=\"source-bold\">経済援助をおこなった</strong>。朴正熙は国民の政治的な権利は抑圧して、軍事力を背景とする<strong class=\"source-bold\">開発<ruby>独裁<rt>どくさい</rt></ruby>体制</strong>をとって、日本からの資本などによって韓国は経済発展を進めたんだ（「<ruby>漢江<rt>ハンガン</rt></ruby>の奇跡」）。</p>\n<blockquote><p>韓国では長い間「クーデタ→軍事政権」という歴史が繰り返されるんだ</p></blockquote>\n<p>ただ、経済発展は大<ruby>財閥<rt>ざいばつ</rt></ruby>が中心で国内の民主化は進まず、<strong class=\"source-bold\">軍事政権への不満</strong>が高まった。朴正熙は<strong class=\"source-bold\"><ruby>戒厳令<rt>かいげんれい</rt></ruby></strong>を出して反対派を<ruby>封<rt>ふう</rt></ruby>じ込め、訪日中の民主化運動の指導者<ruby>金大中<rt>キムデジュン</rt></ruby>を<ruby>拉致<rt>らち</rt></ruby>するなど（<strong class=\"source-bold\">金大中事件</strong>）、民主化運動を弾圧したんだ。また、対外的にはアメリカに依存し、アジアでは<strong class=\"source-bold\">韓国軍だけがベトナム戦争に派兵</strong>した。</p>\n<p>1979年、<strong class=\"source-bold\">朴正熙が暗殺</strong>されて政権は混乱したけど、今度は<strong class=\"source-bold\"><ruby>全斗煥<rt>チョンドゥファン</rt></ruby></strong>が軍部の実権を握った。また軍事政権だよ。朴正熙の暗殺をきっかけに<strong class=\"source-bold\">民主化運動</strong>が盛り上がると、全斗煥は非常戒厳令を出して徹底的に弾圧、野党の<strong class=\"source-bold\"><ruby>金泳三<rt>キムヨンサム</rt></ruby>や金大中が逮捕</strong>され、学生や市民の暴動も武力で鎮圧したよ（<strong class=\"source-bold\"><ruby>光州<rt>こうしゅう</rt></ruby>事件</strong>）。</p>\n<h4><span data-source-color=\"gray\" style=\"color:#777777\">◀</span> <span data-source-color=\"gray\" style=\"color:#777777\"><strong class=\"source-bold\">やっと始まった民主化。残る課題は南北朝鮮の統一だけど……</strong></span></h4>\n<p>1987年に<ruby>汚職<rt>おしょく</rt></ruby>の発覚で始まった反政府運動を抑えられず、<strong class=\"source-bold\">全斗煥が失脚</strong>した。跡を継いだ<strong class=\"source-bold\"><ruby>盧泰愚<rt>ノテウ</rt></ruby></strong>は民主化宣言をおこなうと、<strong class=\"source-bold\">初の大統領直接選挙で当選</strong>、これが<strong class=\"source-bold\">韓国初の平和的な政権交代</strong>だよ。そして、1988年の<strong class=\"source-bold\">ソウル＝オリンピック</strong>をきっかけに<strong class=\"source-bold\">ソ連との対話</strong>を始め、共産圏との和解を目指した。この北方外交により、ソ連の</p>",
  "435": "<h2>435</h2>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">3</span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">戦後の韓国</u></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">帝国主義と第一次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦後の世界</strong></span></p></blockquote>\n<p>ゴルバチョフとの間で<strong class=\"source-bold\">韓ソ国交樹立</strong>を実現し、1991年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南北朝鮮が国連に同時加盟</strong></span>したよ。でも、この国連加盟は順番を間違えた。というのも、法的にはまだ<strong class=\"source-bold\">朝鮮戦争が終わっていない</strong>から、交戦中の2国を国連に加盟させたことになる。東西ドイツの時みたいに、「両国がお互いの“国”を承認して<ruby>講和<rt>こうわ</rt></ruby>条約を結び、その後に国連加盟」っていうふうにすれば、南北朝鮮の統一も進んでいたかもしれない。その後、1992年には<strong class=\"source-bold\">中国とも国交を樹立</strong>し、<strong class=\"source-bold\">台湾政府とは断交</strong>したよ。</p>\n<p>こうして、やっと民主化が進むと、1993年に大統領となった<strong class=\"source-bold\">金泳三</strong>が、もと大統領だった<strong class=\"source-bold\">全斗煥や盧泰愚を逮捕</strong>するなど、汚職や<ruby>腐敗<rt>ふはい</rt></ruby>の一掃に取り組んだ。さらに、1998年にはかつての民主化運動の指導者<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">金大中</strong></span>が大統領となり、北朝鮮に対する<strong class=\"source-bold\">太陽政策</strong>を発表、経済援助などによって北朝鮮との関係を改善し、朝鮮問題の平和的解決を目指したんだ。そして、2000年には<strong class=\"source-bold\">ピョンヤンを訪問</strong>し、北朝鮮の指導者<strong class=\"source-bold\"><ruby>金正日<rt>キムジョンイル</rt></ruby></strong>との<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南北朝鮮首脳会談</strong></span>を実現したよ。太陽政策は次の大統領の<strong class=\"source-bold\"><ruby>盧武鉉<rt>ノムヒョン</rt></ruby></strong>にも継承されたけど、この間に<strong class=\"source-bold\">北朝鮮は<ruby>核<rt>かく</rt></ruby>開発を進め</strong>、2006年には<strong class=\"source-bold\">核実験を強行</strong>、<strong class=\"source-bold\">核保有国</strong>になったんだ！。</p>\n<p>こうした動きから、<strong class=\"source-bold\">太陽政策の見直しとアメリカとの関係強化</strong>を主張して大統領となったのが<strong class=\"source-bold\"><ruby>李明博<rt>イミョンバク</rt></ruby></strong>だね。そして、2013年には<strong class=\"source-bold\">朴正熙の娘の<ruby>朴槿恵<rt>パククネ</rt></ruby></strong>が大統領となった。彼女は<strong class=\"source-bold\">韓国初の女性大統領</strong>で、日本との懸案であった従軍慰安婦問題で歴史的な和解もしたんだけど、スキャンダルで失職しちゃった！。</p>\n<p>続いて大統領となった<strong class=\"source-bold\"><ruby>文在寅<rt>ムンジェイン</rt></ruby></strong>は、北朝鮮の指導者<strong class=\"source-bold\"><ruby>金正恩<rt>キムジョンウン</rt></ruby></strong>との南北朝鮮首脳会談をおこなうなど<strong class=\"source-bold\">北朝鮮との融和</strong>を進める一方で、日本との協定や合意を次々に破棄するなど<strong class=\"source-bold\">極端な反日政策</strong>を打ち出し、<strong class=\"source-bold\">アメリカとの関係も軽視</strong>したんだ。ただ、国内では右派・左派の分断も進んで、2022年には反北朝鮮政策を主張する<strong class=\"source-bold\"><ruby>尹錫悦<rt>ユンソンニョル</rt></ruby></strong>が大統領となり、<strong class=\"source-bold\">日米との関係改善を進めている</strong>よ。</p>\n<p>さて、今回はこれでおしまい。最後に年号 check だ！</p>\n<h3><span data-source-color=\"green\" style=\"color:#315837\">!!</span> <span data-source-color=\"red\" data-source-background=\"white\" style=\"color:#e52715;background-color:#ffffff\">年号</span><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">のツボ</span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">中華人民共和国成立</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1949</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>よ<rt>4</rt></ruby><ruby>苦<rt>9</rt></ruby></strong></span>労の 中国革命）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">「<ruby>大躍進<rt>だいやくしん</rt></ruby>」開始</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1958</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>特<rt>19</rt></ruby></strong></span>別<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>小<rt>5</rt></ruby><ruby>屋<rt>8</rt></ruby></strong></span>で 鉄鋼増産）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">日韓基本条約</strong> ［1<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">965</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>苦<rt>9</rt></ruby><ruby>労<rt>6</rt></ruby><ruby>い<rt>5</rt></ruby></strong></span>つまで 日韓関係）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">文化大革命始まる</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1966</strong></span>］</td><td>（<ruby>毛沢東<rt>もうたくとう</rt></ruby>語録は <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>一<rt>1</rt></ruby><ruby>句<rt>9</rt></ruby><ruby>ム<rt>6</rt></ruby></strong></span>カ<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>ム<rt>6</rt></ruby></strong></span>カ）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">毛沢東の死（文化大革命終息）</strong> ［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1976</strong></span>］</td><td>（文革終われば <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby style=\"ruby-position:under\"><ruby style=\"ruby-position:over\">良<rt>1</rt></ruby><rt>イ</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>な<rt>7</rt></ruby>ろ<ruby>う<rt>6</rt></ruby></strong></span>）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\"><ruby>香港<rt>ホンコン</rt></ruby>返還</strong> ［19<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">97</strong></span>］</td><td>（香港は <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>急<rt>9</rt></ruby><ruby>な<rt>7</rt></ruby></strong></span>返還 一国二制度）</td></tr></tbody></table></div>\n<p>さあ、次回は<strong class=\"source-bold\">東南アジア</strong>だよ。重要なテーマは<strong class=\"source-bold\">ベトナム戦争</strong>！ 米ソの<ruby>冷戦<rt>れいせん</rt></ruby>構造に東南アジアは翻弄されてしまうよ。最後まで気を抜かずに<ruby>頑張<rt>がんば</rt></ruby>ろう。</p>"
};

